// Synthetic public event-stream fixture. Never log Authorization headers or payload secrets.
import{createServer}from'node:http';import{readFileSync}from'node:fs';
const fixture=JSON.parse(readFileSync(new URL('./fixture.json',import.meta.url)));let config={branch:'inline',mode:'missing'},state={acks:0,streams:0,media:0,lastEventId:null,manual:false};
const frame=(event,data,id)=>`${id?'id: '+id+'\n':''}event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
const server=createServer(async(req,res)=>{if(req.url==='/configure'){let b='';for await(const x of req)b+=x;config=JSON.parse(b);state={acks:0,streams:0,media:0,lastEventId:null,manual:false};res.end('{}');return}if(req.url==='/state'){res.setHeader('content-type','application/json');res.end(JSON.stringify(state));return}if(req.url==='/stop'){res.end('{}');server.closeAllConnections();server.close();return}if(req.method==='POST'&&req.url.includes('/ack')){state.acks++;if(config.mode==='ack-error'){res.writeHead(503,{'content-type':'application/json'});res.end(JSON.stringify({error:{type:'api_error',code:'synthetic_ack_failed',message:'synthetic ACK failure',param:null},data:null}));return}res.setHeader('content-type','application/json');res.end(JSON.stringify({success:true,data:{streamId:'fixture-stream',acknowledgedCursor:'descriptor-cursor',sequence:2,replayed:false}}));return}if(req.url.includes('/events/stream')){
 state.streams++;state.lastEventId=req.headers['last-event-id']??null;state.manual=new URL(req.url,'http://localhost').searchParams.get('ack')==='manual';
 const payload=config.payload??fixture[config.branch];const e={id:'descriptor-event',session:'descriptor-session',timestamp:'2026-10-17T00:00:00Z',event:'history.sync',payload};const data={v:1,type:'event',streamId:'fixture-stream',sequence:2,sentAt:e.timestamp,cursor:'descriptor-cursor',event:{id:e.id,organizationId:'fixture-org',projectId:'018f0000-0000-7000-8000-000000000077',type:e.event,source:'runtime',environment:'development',createdAt:e.timestamp,payloadAvailability:'available',payload:{encoding:'base64',contentType:'application/json',data:Buffer.from(JSON.stringify(e)).toString('base64')},replayableUntil:null,metadataExpiresAt:'2026-10-18T00:00:00Z'}};
 res.writeHead(200,{'content-type':'text/event-stream'});const wire=frame('ready',{v:1,type:'ready',streamId:'fixture-stream',sequence:1,heartbeatIntervalMs:15000})+frame('event',data,'descriptor-cursor');res.write(wire.slice(0,123));res.write(wire.slice(123));return}
 state.media++;res.writeHead(404);res.end();});server.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({baseUrl:'http://127.0.0.1:'+server.address().port,node:process.version})));process.on('SIGTERM',()=>{server.closeAllConnections();server.close()});
